import{_ as i,b as l,c as o,g as r}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"机器人学","description":"","frontmatter":{"title":"机器人学","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/26.md","filePath":"articles/ai/books/ai-modern-approach/26.md"}'),a={name:"articles/ai/books/ai-modern-approach/26.md"};function s(n,t,e,d,g,c){return l(),o("div",null,[...t[0]||(t[0]=[r('<p>第 26 章介绍机器人学的核心问题，涵盖感知、定位、规划与控制。重点包括：</p><h2 id="机器人运动学" tabindex="-1">机器人运动学</h2><ul><li><strong>差速驱动</strong>：线速度 v = (vᵣ + vₗ) / 2，角速度 ω = (vᵣ - vₗ) / d</li><li><strong>配置空间（C-Space）</strong>：将机器人膨胀为点，障碍物相应膨胀</li><li>工作空间与配置空间的映射</li></ul><h2 id="定位-localization" tabindex="-1">定位（Localization）</h2><ul><li><strong>马尔可夫定位</strong>：信念 Bel(x) 的预测-更新循环</li><li><strong>扩展卡尔曼滤波（EKF）</strong>：线性化近似，适合单峰分布</li><li><strong>粒子滤波（PF）</strong>：非参数表示，适合多峰分布和全局定位</li><li>起始位置未知时应选用粒子滤波</li></ul><h2 id="同时定位与建图-slam" tabindex="-1">同时定位与建图（SLAM）</h2><ul><li><strong>问题定义</strong>：在未知环境中同时估计机器人位姿和地图</li><li><strong>Graph-SLAM</strong>：节点表示位姿，边表示约束，全局优化误差</li><li>相比 EKF-SLAM 的优势：大规模地图、计算效率、收敛性</li></ul><h2 id="路径规划" tabindex="-1">路径规划</h2><ul><li><strong>A* 算法</strong>：已知全局地图中的最优路径搜索</li><li><strong>RRT（快速随机扩展树）</strong>：适用于高维空间和未知环境</li><li><strong>D* Lite</strong>：动态障碍物环境中的实时重规划</li></ul><h2 id="控制" tabindex="-1">控制</h2><ul><li><strong>PID 控制</strong>：u(t) = Kₚ·e(t) + Kᵢ·∫e(t)dt + Kd·de/dt</li><li>速度跟踪、姿态控制等闭环反馈</li></ul><h2 id="系统设计示例" tabindex="-1">系统设计示例</h2><ul><li><strong>自主清扫机器人</strong>：传感器（激光雷达、里程计、摄像头）、SLAM 定位、覆盖路径规划（Z 字形 / 随机覆盖）、低电量回充</li><li>仿真环境训练与真实道路部署的安全性评估</li></ul>',13)])])}const u=i(a,[["render",s]]);export{p as __pageData,u as default};
